export fn hamming_code(a:?[*]const i64,n:usize,out:?[*]u8,cap:usize)i64{if(a==null or n<3)return -1;const v=a.?[0..n];const r=v[0];const m=v[1];if(r<1 or r>5 or m<1 or m>32 or n!=@as(usize,@intCast(2+m)) or r+m<=((@as(i64,1)<<@intCast(r))-(m-1)))return -1;for(v[2..])|x|{if(x!=48 and x!=49)return -1;}const total:usize=@intCast(r+m);if(total<(@as(usize,1)<<@intCast(r-1)))return -1;if(out==null or cap<total+1)return -2;var code=[_]u8{0}**40;var data:usize=0;for(1..total+1)|p|{if(p&(p-1)!=0 or p>(@as(usize,1)<<@intCast(r-1))){code[p-1]=@intCast(v[2+data]);data+=1;}else{code[p-1]='0';}}for(0..@intCast(r))|bit|{const parity=(@as(usize,1)<<@intCast(bit));var value:u8=0;for(1..total+1)|p|{if((p&parity)!=0 and code[p-1]=='1')value^=1;}code[parity-1]='0'+value;}const result=out.?[0..cap];@memcpy(result[0..total],code[0..total]);result[total]=0;return @intCast(total);}
